func:
// Gộp mọi gói của một thiết bị thành một trạng thái và phát hiện lúc chuyển trạng thái.
// Ra 1: trạng thái (airgas/<dev>/state) · Ra 2: sự kiện cảnh báo · Ra 3: phản hồi lệnh (ack)
const parts = msg.topic.split('/');
const dev = parts[1];
const kind = parts[0] === 'airquality' ? 'air' : parts[2];
const p = msg.payload;

if (kind === 'ack') {
    return [null, null, { topic: dev, payload: p }];
}

const all = flow.get('devices') || {};
const prev = all[dev] || { device: dev, online: false, valve: 'open', fan: 0 };
const s = Object.assign({}, prev);

switch (kind) {
    case 'reading':
        s.gas = { ppm: p.ppm, mv: p.mv, threshold: p.threshold, alarm: !!p.alarm, sim: !!p.sim, fault: !!p.fault };
        break;
    case 'air':
        s.air = { co2: p.co2_ppm, mv: p.mv, threshold: p.threshold, poor: !!p.poor, sim: !!p.sim, fault: !!p.fault };
        break;
    case 'info':
        s.fw = p.fw; s.ip = p.ip; s.rssi = p.rssi; s.sim = p.sim;
        if (p.valve) s.valve = p.valve;
        if (typeof p.fan === 'number') s.fan = p.fan;
        break;
    case 'status':
        s.online = String(p).trim() === 'online';
        break;
    default:
        return null;
}
// a reading or info only arrives from a live device
if (kind !== 'status') s.online = true;

let level = 'BINH_THUONG';
if (s.gas && s.gas.alarm) level = 'NGUY_HIEM';
else if (s.air && s.air.poor) level = 'KHONG_KHI_KEM';
else if ((s.gas && s.gas.fault) || (s.air && s.air.fault)) level = 'LOI_CAM_BIEN';
s.level = level;
// còi do ESP32 tự điều khiển (gas_buzzer.c): suy ra từ cờ báo động giống firmware
s.buzzer = (s.gas && s.gas.alarm) ? 'fast' : ((s.air && s.air.poor) ? 'slow' : 'off');
s.updated = new Date().toISOString();
all[dev] = s;
flow.set('devices', all);

// ---- sự kiện: chỉ khi trạng thái đổi, để không spam tin nhắn
const events = [];
const was = prev.level || 'BINH_THUONG';
const sim = (s.gas && s.gas.sim) || (s.air && s.air.sim);
const tag = sim ? '[GIẢ LẬP] ' : '';
const gasPpm = s.gas ? Math.round(s.gas.ppm) : '?';
const co2 = s.air ? Math.round(s.air.co2) : '?';
if (level !== was) {
    if (level === 'NGUY_HIEM') {
        events.push({ type: 'danger', text: `🚨 ${tag}RÒ RỈ GAS ~${gasPpm} ppm tại ${dev}. Thiết bị đã khoá van, bật quạt hút và còi.` });
    } else if (was === 'NGUY_HIEM') {
        events.push({ type: 'safe', text: s.valve === 'closed'
            ? `✅ ${tag}Nồng độ gas đã về mức an toàn (~${gasPpm} ppm). Van vẫn KHOÁ: mở dashboard và bấm "Xác nhận an toàn – Mở van".`
            : `✅ ${tag}Nồng độ gas đã về mức an toàn (~${gasPpm} ppm).` });
    }
    if (level === 'KHONG_KHI_KEM') {
        events.push({ type: 'poor', text: `⚠️ ${tag}Không khí kém ~${co2} ppm CO2eq tại ${dev}. Quạt hút đang chạy.` });
    }
    if (level === 'LOI_CAM_BIEN') {
        const which = [s.gas && s.gas.fault ? 'MQ-2' : null, s.air && s.air.fault ? 'MQ-135' : null].filter(Boolean).join(', ');
        events.push({ type: 'fault', text: `🔌 ${which} mất tín hiệu (không có điện hoặc lỏng dây VCC).` });
    }
}
if (prev.online && !s.online) {
    events.push({ type: 'offline', text: `📴 ${dev} mất kết nối với broker.` });
}
if (prev.valve !== s.valve && kind === 'info' && prev.valve) {
    events.push({ type: 'valve', text: s.valve === 'closed' ? `🔒 Van gas đã KHOÁ.` : `🔓 Van gas đã MỞ lại.` });
}

const stateMsg = { topic: `airgas/${dev}/state`, payload: s, retain: true };
node.status({ fill: level === 'BINH_THUONG' ? 'green' : (level === 'NGUY_HIEM' ? 'red' : 'yellow'),
              shape: s.online ? 'dot' : 'ring', text: `${dev}: ${level} · van ${s.valve} · quạt ${s.fan}%` });
return [stateMsg, events.map(e => ({ topic: dev, event: e.type, payload: e.text, state: s })), null];

// Home Assistant không cần 3 gói/giây: gửi khi mức cảnh báo / van / quạt / online đổi,
// còn lại tối đa 5 giây một lần.
const s = msg.payload;
const key = [s.level, s.valve, s.fan, s.buzzer, s.online].join('|');
const last = context.get('last') || { key: '', t: 0 };
const now = Date.now();
if (key !== last.key || now - last.t >= 5000) {
    context.set('last', { key, t: now });
    return msg;
}
return null;

// Chặn lặp: cùng một loại sự kiện của cùng thiết bị chỉ gửi lại sau 30 giây
// (cảm biến dao động quanh ngưỡng sẽ không làm nổ tin nhắn).
const key = msg.topic + ':' + msg.event;
const sent = context.get('sent') || {};
const now = Date.now();
if (sent[key] && now - sent[key] < 30000) return null;
sent[key] = now;
context.set('sent', sent);
return msg;

// Soạn tin Discord. Webhook lấy từ biến môi trường DISCORD_WEBHOOK_URL (node-red/.env).
// ESP32 đã tự gửi Discord khi rò gas, không khí kém và khi khoá van, nên ở đây chỉ gửi
// các tin thiết bị không tự gửi được: an toàn chờ xác nhận, mất tín hiệu cảm biến,
// mất kết nối, van mở lại.
const FROM_ESP32 = ['danger', 'poor'];
if (FROM_ESP32.includes(msg.event) || (msg.event === 'valve' && msg.state && msg.state.valve === 'closed')) {
    node.status({ fill: 'grey', shape: 'dot', text: msg.event + ': ESP32 tự gửi' });
    return null;
}
const url = env.get('DISCORD_WEBHOOK_URL');
if (!url) {
    node.status({ fill: 'grey', shape: 'ring', text: 'chưa cấu hình DISCORD_WEBHOOK_URL (.env)' });
    return null;
}
node.status({ fill: 'blue', shape: 'dot', text: 'gửi: ' + msg.event });
msg.url = url;
msg.method = 'POST';
msg.headers = { 'content-type': 'application/json' };
msg.payload = { username: 'Node-RED · Trạm cảnh báo gas', content: `**${msg.topic}** – ${msg.payload}` };
return msg;

// Discord trả 204 No Content khi nhận tin
if (msg.statusCode >= 200 && msg.statusCode < 300) {
    node.status({ fill: 'green', shape: 'dot', text: 'đã gửi ' + new Date().toLocaleTimeString('vi-VN') });
} else {
    node.status({ fill: 'red', shape: 'dot', text: 'lỗi ' + msg.statusCode });
    node.warn(msg.payload);
}
return null;

const t = new Date().toISOString();
msg.payload = `${t},${msg.topic},${msg.event},"${String(msg.payload).replace(/"/g, "'")}"`;
msg.filename = '/data/logs/alerts.csv';
return msg;

// Tách trạng thái 3 cơ cấu chấp hành, chỉ gửi khi đổi
const s = msg.payload;
const now = { valve: s.valve, fan: s.fan, buzzer: s.buzzer, online: s.online };
const last = context.get('last') || {};
context.set('last', now);
const out = [null, null, null];
if (now.valve !== last.valve || now.online !== last.online) out[0] = { payload: s.valve, online: s.online };
if (now.fan !== last.fan || now.online !== last.online) out[1] = { payload: s.fan, online: s.online };
if (now.buzzer !== last.buzzer || now.online !== last.online) out[2] = { payload: s.buzzer, online: s.online };
return out;

const closed = msg.payload === 'closed';
node.status({ fill: closed ? 'red' : 'green', shape: msg.online ? 'dot' : 'ring',
              text: closed ? 'Van ĐÃ KHOÁ' : 'Van đang mở' });
return null;

const pct = Number(msg.payload) || 0;
node.status({ fill: pct ? 'blue' : 'grey', shape: msg.online ? 'dot' : 'ring',
              text: pct ? `Quạt hút chạy ${pct}%` : 'Quạt tắt' });
return null;

const t = { fast: 'Còi bíp nhanh (rò gas)', slow: 'Còi bíp chậm (không khí kém)', off: 'Còi im' };
node.status({ fill: msg.payload === 'off' ? 'grey' : 'red', shape: msg.online ? 'dot' : 'ring',
              text: t[msg.payload] || msg.payload });
return null;

// Tách trạng thái ra từng widget: thẻ trạng thái, 2 đồng hồ, 2 đường biểu đồ.
const s = msg.payload;
const gas = s.gas && !s.gas.fault ? Math.round(s.gas.ppm) : null;
const co2 = s.air && !s.air.fault ? Math.round(s.air.co2) : null;
const chart = [];
if (msg.topic.endsWith('/state') && s.gas && gas !== null) chart.push({ topic: 'Gas (ppm)', payload: gas });
if (s.air && co2 !== null) chart.push({ topic: 'CO2eq (ppm)', payload: co2 });
return [
    { payload: s },
    gas === null ? null : { payload: gas },
    co2 === null ? null : { payload: co2 },
    chart,
];

// biểu đồ: mỗi đường 1 điểm / 5 giây
const last = context.get(msg.topic) || 0;
if (Date.now() - last < 5000) return null;
context.set(msg.topic, Date.now());
return msg;

const a = msg.payload || {};
msg.payload = (a.ok ? '✔ ' : '✖ ') + 'Thiết bị ' + (a.ok ? 'đã nhận' : 'từ chối') + ' lệnh ' + (a.cmd || '') +
    (a.msg ? ': ' + a.msg : '');
return msg;

// Home Assistant MQTT discovery: một thiết bị, các cảm biến đọc từ airgas/<dev>/state
const DEV = 'Gas-Monitor-01';
const id = DEV.toLowerCase().replace(/[^a-z0-9]+/g, '_');
const state = `airgas/${DEV}/state`;
const device = { identifiers: [id], name: 'Trạm cảnh báo gas', manufacturer: 'Nhóm 12 – HUIT',
                 model: 'ESP32 + MQ-2 + MQ-135' };
const avail = { availability_topic: `airgas/${DEV}/status`, payload_available: 'online', payload_not_available: 'offline' };
const out = [];
function cfg(component, key, body) {
    out.push({ topic: `homeassistant/${component}/${id}_${key}/config`, retain: true,
               payload: Object.assign({ unique_id: `${id}_${key}`, object_id: `${id}_${key}`, device }, avail, body) });
}
cfg('sensor', 'gas', { name: 'Nồng độ gas', state_topic: state, unit_of_measurement: 'ppm', icon: 'mdi:gas-cylinder',
    value_template: "{{ value_json.gas.ppm if value_json.gas is defined and not value_json.gas.fault else none }}" });
cfg('sensor', 'co2', { name: 'CO2 tương đương', state_topic: state, unit_of_measurement: 'ppm', icon: 'mdi:molecule-co2',
    value_template: "{{ value_json.air.co2 if value_json.air is defined and not value_json.air.fault else none }}" });
cfg('sensor', 'level', { name: 'Mức cảnh báo', state_topic: state, icon: 'mdi:alert', value_template: '{{ value_json.level }}' });
cfg('binary_sensor', 'gas_alarm', { name: 'Rò rỉ gas', device_class: 'gas', state_topic: state,
    value_template: "{{ 'ON' if value_json.level == 'NGUY_HIEM' else 'OFF' }}" });
cfg('sensor', 'valve', { name: 'Van gas', state_topic: state, icon: 'mdi:valve', value_template: '{{ value_json.valve }}' });
cfg('sensor', 'fan', { name: 'Quạt hút', state_topic: state, unit_of_measurement: '%', icon: 'mdi:fan',
    value_template: '{{ value_json.fan }}' });
cfg('sensor', 'buzzer', { name: 'Còi báo động', state_topic: state, icon: 'mdi:bullhorn',
    value_template: "{{ {'fast': 'Bíp nhanh', 'slow': 'Bíp chậm', 'off': 'Im'}[value_json.buzzer] | default('?') }}" });
cfg('button', 'valve_open', { name: 'Xác nhận an toàn – Mở van', command_topic: `airgas/${DEV}/cmd`,
    payload_press: '{"valve":"open"}', icon: 'mdi:valve-open' });
cfg('button', 'valve_close', { name: 'Khoá van', command_topic: `airgas/${DEV}/cmd`,
    payload_press: '{"valve":"close"}', icon: 'mdi:valve-closed' });
cfg('button', 'fan_test', { name: 'Thử quạt 10 giây', command_topic: `airgas/${DEV}/cmd`,
    payload_press: '{"fan_test":60,"duration":10}', icon: 'mdi:fan-alert' });
cfg('button', 'recalibrate', { name: 'Hiệu chuẩn cảm biến', command_topic: `airgas/${DEV}/cmd`,
    payload_press: '{"recalibrate":true}', icon: 'mdi:tune-vertical', entity_category: 'config' });
cfg('sensor', 'fw', { name: 'Phiên bản firmware', state_topic: state, icon: 'mdi:chip', entity_category: 'diagnostic',
    value_template: '{{ value_json.fw | default(none) }}' });
cfg('sensor', 'rssi', { name: 'Sóng Wi-Fi', state_topic: state, unit_of_measurement: 'dBm', device_class: 'signal_strength',
    entity_category: 'diagnostic', value_template: '{{ value_json.rssi | default(none) }}' });
node.status({ fill: 'green', shape: 'dot', text: out.length + ' cấu hình đã gửi' });
return [out];

// mỗi thiết bị 1 dòng / 10 giây vào /data/logs/airgas.csv
const s = msg.payload;
const last = context.get(s.device) || 0;
if (Date.now() - last < 10000) return null;
context.set(s.device, Date.now());
const out = [];
if (!context.get('header')) {
    context.set('header', true);
    out.push({ payload: 'time,device,level,gas_ppm,gas_mv,co2_ppm,co2_mv,valve,fan,online,sim', filename: '/data/logs/airgas.csv' });
}
const g = s.gas || {}, a = s.air || {};
out.push({ payload: [s.updated, s.device, s.level, g.ppm ?? '', g.mv ?? '', a.co2 ?? '', a.mv ?? '', s.valve, s.fan,
                     s.online, !!(g.sim || a.sim)].join(','), filename: '/data/logs/airgas.csv' });
return [out];
